import {MONSTERS,Adventure,selectPool,makeOptions,scramble} from './engine.mjs';
import {IslandAudio,WordSpeaker} from './audio.mjs';
import {BattleAction} from './battle.mjs';
import {MonsterPark} from './park.mjs';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sprite=(i,cls='')=>`<div class="monster monster-${i} ${cls}" role="img" aria-label="${MONSTERS[i].name}"></div>`;
const DEFAULTS={mode:'mixed',timed:false,seconds:25,course:'ALL',scope:'all',groupIds:[],sfx:true,music:true,musicVolume:.32,sfxVolume:.5,voiceVolume:1};
let storageOK=true;
function read(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value??fallback;}catch{storageOK=false;return fallback;}}
let settings={...DEFAULTS,...read('wordling-settings-v1',{})};
let progress={captured:{},words:{},adventures:0,bestScore:0,...read('wordling-progress-v1',{})};
function save(){try{localStorage.setItem('wordling-settings-v1',JSON.stringify(settings));localStorage.setItem('wordling-progress-v1',JSON.stringify(progress));}catch{storageOK=false;}}
let data,view='home',game=null,round=null,paused=false,score=0,sessionWords=[],timerId,remainingMs=0,lastTick=0,waitingForAudio=false,audioDeadline,sessionMode,voiceToken=0,speaking=false,modalPaused=false,park=null,parkReturnView='home',parkWasPaused=false;
let actionBusy=false,battleAction=null;
const sound=new IslandAudio(settings),speaker=new WordSpeaker(sound);
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('visible'),3600);}
function sfx(kind){sound.effect(kind);}
function stopPark(){park?.destroy();park=null;}
function header(gameHeader=false){return `<header class="${gameHeader?'game-header':''}"><button class="brand" data-action="home" aria-label="單字獸島首頁"><span class="brand-icon">${icon('leaf')}</span><span class="brand-title">單字獸島<small>WORDLING ISLAND</small></span></button><nav aria-label="主選單"><button class="nav-button" data-action="park" title="夥伴園區">${icon('park')}夥伴園區</button><button class="nav-button" data-action="sound-settings" title="音樂、音效與美語設定">${icon('music')}聲音設定</button><button class="nav-button" data-action="records" title="學習足跡">${icon('star')}學習足跡</button><button class="nav-button" data-action="${gameHeader?'pause':'help'}" title="${gameHeader?'暫停':'遊戲說明'}">${icon(gameHeader?'pause':'sparkle')}${gameHeader?'暫停':'玩法'}</button></nav></header>`;}
function pool(){if(settings.scope==='custom'&&!settings.groupIds.length)return [];return selectPool(data,settings.course,settings.scope==='all'?[]:settings.groupIds);}
function courseName(){if(settings.scope==='all')return settings.course==='ALL'?'CET + FET 全部單字':`${settings.course} 全部單字`;return `${settings.course==='ALL'?'CET + FET':settings.course} · 已選 ${settings.groupIds.length} 組`;}
function setChoice(action,value,label,active,extra=''){return `<button type="button" class="segment ${active?'active':''}" data-action="${action}" data-value="${value}" aria-pressed="${active}" ${extra}>${label}</button>`;}
function selectedSummary(){if(settings.scope==='all')return settings.course==='ALL'?'全部 CET Week + 全部 FET Lesson':settings.course==='CET'?'全部 CET Week':'全部 FET Lesson';const selected=data.groups.filter(g=>settings.groupIds.includes(g.id));return selected.slice(0,3).map(g=>`${g.course} ${g.label}`).join('、')+(selected.length>3?`，共 ${selected.length} 組`:'')||'尚未選擇課次';}
function unitPickerMarkup(){const courses=settings.course==='ALL'?['CET','FET']:[settings.course];return `<div class="course-picker"><div class="unit-actions"><button class="text-button ${settings.scope==='all'?'all-selected':''}" data-action="all-units">${settings.scope==='all'?'✓ ':''}全部課次</button><button class="text-button" data-action="clear-units">清除選取</button><span class="word-count">${pool().length} 個單字</span></div>${courses.map(course=>`<section class="course-unit-panel" aria-label="${course==='CET'?'CET Week 選擇':'FET Lesson 選擇'}"><div class="unit-panel-heading"><strong>${course==='CET'?'CET · 選擇 Week':'FET · 選擇 Lesson'}</strong><span>可複選</span><button class="text-button" data-action="course-all" data-course="${course}">全選 ${course}</button></div><div class="visible-unit-grid">${data.groups.filter(g=>g.course===course).map(g=>`<button class="unit-option ${settings.scope==='custom'&&settings.groupIds.includes(g.id)?'selected':''}" data-action="unit" data-value="${g.id}" aria-label="${course} ${g.label}" aria-pressed="${settings.scope==='custom'&&settings.groupIds.includes(g.id)}" title="${esc(g.topic||g.label)}">${g.label}${g.is_review?'<small>複習</small>':''}</button>`).join('')}</div></section>`).join('')}<p class="selection-summary" role="status">${esc(selectedSummary())}</p></div>`;}
function renderHome(openUnits=false){stopPark();view='home';sound.setScene('home');const groups=data.groups.filter(g=>settings.course==='ALL'||g.course===settings.course);const count=pool().length;app.innerHTML=`${header()}<main class="home"><div class="home-layout"><section class="home-copy"><div class="eyebrow">A LITTLE WORD. A NEW FRIEND.</div><h1>聽見單字，<br>遇見<span style="color:var(--green)">新夥伴。</span></h1><p class="intro">帶上你的捕捉電腦，出發去單字獸島！<br>聽一聽、選一選，讓每個英文單字變成可愛的朋友。</p><div class="setup">${!storageOK?'<div class="saved-warning">此瀏覽器目前無法保存紀錄，仍可遊玩；請勿使用私密瀏覽以保留進度。</div>':''}<div class="setup-section"><div class="setup-label"><span class="step-num">1</span>今天想怎麼冒險？</div><div class="segments">${setChoice('mode','choice',icon('sound')+'聽音選字',settings.mode==='choice')}${setChoice('mode','spell','Aa 字母拼拼',settings.mode==='spell')}${setChoice('mode','mixed',icon('sparkle')+'混合冒險',settings.mode==='mixed')}</div></div><div class="setup-section"><div class="setup-label"><span class="step-num">2</span>選擇冒險步調<span class="label-end">慢慢學，也很棒</span></div><div class="time-line"><div class="segments">${setChoice('timed','false','∞ 不限時間',!settings.timed)}${setChoice('timed','true',icon('clock')+'限時挑戰',settings.timed)}</div>${settings.timed?`<select class="small-select" id="seconds" aria-label="每題秒數">${[15,25,40].map(n=>`<option value="${n}" ${settings.seconds===n?'selected':''}>每題 ${n} 秒</option>`).join('')}</select>`:''}</div></div><div class="setup-section"><div class="setup-label"><span class="step-num">3</span>帶上哪一本單字書？<span class="label-end">2026 秋季・G1</span></div><div class="course-segments">${[['ALL','全部一起'],['CET','CET 單字'],['FET','FET 單字']].map(([value,label])=>`<button class="course-chip ${settings.course===value?'active':''}" data-action="course" data-value="${value}" aria-pressed="${settings.course===value}">${label}</button>`).join('')}</div>${unitPickerMarkup()}</div><button class="start-button" data-action="start" ${count<1?'disabled':''}><span>${icon('leaf')}開始冒險</span>${icon('arrow')}</button><p class="setup-note">${count<1?'請至少選擇一組單字':`本次字庫 ${count} 個單字 · 5 隻小怪 + 1 隻魔王`}<br>自然美語 Jenny · 點一下畫面啟用冒險配樂</p></div></section><aside class="hero-column" aria-label="單字獸島的夥伴"><div class="float-sticker">每天一點點，<br>英文多一點！<span>LET’S GROW TOGETHER</span></div><div class="hero-scene"><div class="scene-top"><span class="dot"></span>芽光森林 · SUNNY MEADOW</div>${sprite(0,'hero-monster')}${sprite(1,'hero-friend')}<span class="word-bubble">hello!</span><img class="hero-player" src="assets/researcher-v2.png" alt="銅橘髮、戴護目鏡的原創小研究員，手持捕捉電腦"><div class="hero-caption"><span class="caption-icon">${icon('sparkle')}</span><div><strong>下一位夥伴，正在等你。</strong><small>聽懂一個單字，開啟一段小小冒險。</small></div></div></div><div class="hero-bottom"><span class="hero-feature">${icon('sound')}聽音練習</span><span class="hero-feature">${icon('book')}課內單字</span><span class="hero-feature">${icon('star')}原創夥伴收集</span></div></aside></div><footer class="island-line"><span><strong>小小單字，大大世界。</strong> 每一次練習，都算數。</span><span class="footer-note">KCIS G1 · ${data.summary.unique_word_count} WORDS · MADE FOR LITTLE EXPLORERS</span></footer></main>`;}
function stopSpeech(){voiceToken++;speaker.stop();speaking=false;clearTimeout(audioDeadline);$('.audio-button')?.classList.remove('speaking');}
function speak(word,{first=false}={}){
 stopSpeech();const token=voiceToken,questionRound=round,isQuestionAudio=view==='game'&&round?.phase==='question'&&!paused&&word===round.card.english;
 if(first&&isQuestionAudio)waitingForAudio=true;
 const finish=()=>{if(token!==voiceToken)return;speaking=false;$('.audio-button')?.classList.remove('speaking');if(isQuestionAudio&&round===questionRound){waitingForAudio=false;lastTick=Date.now();}clearTimeout(audioDeadline);updateVoiceStatus();};
 speaker.play(word,{onstart:()=>{if(token!==voiceToken)return;speaking=true;$('.audio-button')?.classList.add('speaking');updateVoiceStatus('正在播放標準美語…');},onend:finish,onerror:message=>{if(token!==voiceToken)return;finish();if(first&&isQuestionAudio)waitingForAudio=true;toast(message);}}).catch(()=>{finish();if(first&&isQuestionAudio)waitingForAudio=true;toast('語音暫時無法播放，請按喇叭再試一次。');});
 audioDeadline=setTimeout(()=>{if(token===voiceToken&&first&&waitingForAudio){stopSpeech();toast('語音尚未完成，請按喇叭重試；倒數暫停中。');}},20000);
}
function updateVoiceStatus(message){const el=$('#voice-status');if(el)el.textContent=message||(speaker.fallback?'目前使用裝置美語備援；重新載入可再試自然錄音。':speaker.manifest?'Jenny · 美國英語 · 自然語速，已預載所有單字':'美語錄音準備中…');}
function startGame(){stopBattleAction();if(!pool().length)return;window.scrollTo(0,0);save();sfx('start');stopSpeech();clearInterval(timerId);game=new Adventure(pool());score=0;sessionWords=[];sessionMode=settings.mode;paused=false;view='game';nextRound();timerId=setInterval(tick,120);}
function nextRound(){stopBattleAction();if(game.done)return finish();stopSpeech();const card=game.draw();let mode=sessionMode;if(mode==='mixed')mode=(game.correct%2===0?'choice':'spell');round={card,mode,phase:'question',options:makeOptions(card,game.pool),letters:scramble(card.english),selected:[],wrong:[],message:'',assisted:false,attempts:0,result:null};remainingMs=settings.seconds*1000;lastTick=Date.now();renderBattle();speak(card.english,{first:true});}
function currentMonster(){if(round?.result?.captured)return round.result.monster;return game.boss?5:game.stage;}
function renderBattle(){stopPark();view='game';sound.setScene(game.boss?'boss':'field');const mi=currentMonster(),m=MONSTERS[mi],isBoss=mi===5;const roundIndex=game.correct+1;app.innerHTML=`${header(true)}<main class="game-page"><div class="adventure-toolbar"><div class="journey-info"><strong>${isBoss?'星花守護者的考驗':'芽光森林探險'}</strong><span>／ ${esc(courseName())}</span></div><div class="journey-path" aria-label="冒險進度">${MONSTERS.map((_,i)=>`${i?'<span class="path-line"></span>':''}<span class="path-node ${game.captures.includes(i)?'complete':i===mi?'current':''}">${game.captures.includes(i)?'✓':i===5?'★':i+1}</span>`).join('')}</div></div><section class="arena ${isBoss?'boss':''}" aria-label="怪物對戰場景"><span class="location-label">${icon('leaf')}芽光森林 · ${isBoss?'守護者領地':'晴朗'}</span><div class="monster-status"><div class="monster-name"><strong>${m.name}</strong><span class="type-label">${isBoss?'BOSS · ':''}${m.type}</span></div><div class="hp-line"><span>${isBoss?'HP':'LINK'}</span><div class="hp-track" role="progressbar" aria-label="${isBoss?'魔王血量':'捕捉連結'}" aria-valuemin="0" aria-valuemax="${isBoss?3:1}" aria-valuenow="${isBoss?game.bossHp:round.phase==='success'?0:1}"><div class="hp-fill" style="width:${isBoss?game.bossHp/3*100:round.phase==='success'?0:100}%"></div></div></div><div class="hp-count">${isBoss?`能量 ${game.bossHp} / 3 · 答對一題削減一格`:'野生夥伴 · 等待你的單字訊號'}</div></div><div class="encounter-bubble" id="encounter-bubble">${isBoss?'花冠星龍出現了！<br>完成 3 道考驗，成為新朋友。':`${m.name} 從草叢探出頭了！<br>聽出單字，送出友好的訊號吧。`}</div><div class="enemy-wrap ${isBoss?'boss-enemy':''} ${round.phase==='success'&&round.result?.captured?'captured':''}" id="enemy-wrap"><div class="enemy-shadow"></div>${sprite(mi,'enemy')}<span class="enemy-word ${round.phase==='question'?'':'revealed'}" id="enemy-word">${round.phase==='question'?'? '.repeat(Math.min(round.card.english.length,8)).trim():esc(round.card.english)}</span></div><div class="hero-actor" id="hero-actor"><img class="arena-player" src="assets/researcher-v2.png" alt="原創單字研究員拿著捕捉電腦"><div class="hero-action-sprite" aria-hidden="true"></div></div><div class="action-caption" id="action-caption" role="status" aria-live="polite"></div><div class="player-status"><strong>小小單字研究員</strong><small>WORDLINK 已就緒 <span style="color:#75a979">● ● ●</span></small></div><div class="timer-badge" id="timer-badge">${icon(settings.timed?'clock':'leaf')}<span id="time-left">${settings.timed?Math.ceil(remainingMs/1000)+'s':'∞ 慢慢來'}</span></div>${paused?pauseMarkup():''}</section><section class="computer-shell" aria-label="捕捉電腦"><div class="computer-top"><span class="led"></span>WORDLINK · CAPTURE TERMINAL<span class="hardware-right">•••</span></div><div class="computer-screen" id="computer-screen">${questionMarkup()}</div></section><div class="game-bottom"><div class="game-stats"><span>${icon('book')}已捕捉 <b id="capture-count">${game.captures.length}</b> / 6</span><span>${icon('star')}<b id="score-count">${score}</b> 分</span><span>${round.mode==='choice'?'聽音選字':'字母拼拼'}</span></div><span class="keyboard-note">空白鍵重聽 · ${round.mode==='choice'?'數字 1–4 選答案':'鍵盤輸入字母 · Backspace 返回'} · Esc 暫停</span></div></main>`;if(round.phase==='success')renderResult();else if(round.phase==='timeout')renderTimeout();}
function questionMarkup(){return `<div class="question-top"><div class="question-label"><button class="audio-button" data-action="replay" title="再聽一次（空白鍵）" aria-label="再聽一次單字">${icon('sound')}</button><div><strong>${round.mode==='choice'?'你聽到了哪個單字？':'把字母排成你聽到的單字！'}</strong><small>${round.mode==='choice'?'聽一聽，選對單字就能送出捕捉訊號。':'依序點字母；點上方的字母可以退回。連字號也要排入喔。'}</small></div></div><div class="question-actions"><button class="help-button" data-action="hint">單字提示</button></div></div>${round.mode==='choice'?`<div class="choice-grid">${round.options.map((w,i)=>`<button class="answer-choice ${round.wrong.includes(w)?'wrong':''}" data-action="answer" data-word="${esc(w)}" ${round.wrong.includes(w)?'disabled':''}><span class="key">${i+1}</span>${esc(w)}</button>`).join('')}</div>`:spellMarkup()}<div class="feedback ${round.message.startsWith('提示')?'good':''}" id="feedback" role="status" aria-live="polite">${esc(round.message)}</div>`;}
function spellMarkup(){return `<div class="spell-slots" aria-label="已排列的字母">${[...round.card.english].map((_,i)=>round.selected[i]!==undefined?`<button class="letter-slot filled" data-action="unletter" data-index="${i}" aria-label="退回第 ${i+1} 個字母 ${round.letters.find(t=>t.id===round.selected[i]).letter}">${esc(round.letters.find(t=>t.id===round.selected[i]).letter)}</button>`:`<span class="letter-slot" aria-label="第 ${i+1} 個空格"></span>`).join('')}</div><div class="letter-bank" aria-label="可選的字母">${round.letters.map(t=>`<button class="letter-tile" data-action="letter" data-id="${t.id}" aria-label="選取字母 ${t.letter}" ${round.selected.includes(t.id)?'disabled':''}>${esc(t.letter)}</button>`).join('')}</div><div class="spell-tools"><button data-action="backspace">${icon('back')}退一格</button><button data-action="clear-letters">重新排列</button></div>`;}
function updateQuestion(){const screen=$('#computer-screen');if(screen)screen.innerHTML=questionMarkup();if(speaking)$('.audio-button')?.classList.add('speaking');}
function submitAnswer(value){if(actionBusy||!round||round.phase!=='question'||paused||modal.open)return;const correct=value===round.card.english;round.attempts++;const result=game.answer(correct);round.result=result;
 if(!correct){round.message='差一點點！按喇叭再聽一次，你可以的。';if(round.mode==='choice')round.wrong.push(value);else round.selected=[];updateQuestion();runBattleAction('wrong',currentMonster());return;}
 round.phase='success';waitingForAudio=false;stopSpeech();const gained=round.assisted?50:round.attempts===1?100:70;score+=gained;
 const word=round.card.english;const record=progress.words[word]||{correct:0,attempts:0};record.correct++;record.attempts+=round.attempts;record.lastPracticed=new Date().toISOString();progress.words[word]=record;
 if(!sessionWords.find(c=>c.id===round.card.id))sessionWords.push(round.card);
 if(result.captured){const id=MONSTERS[result.monster].id;progress.captured[id]=(progress.captured[id]||0)+1;}save();
 const mi=result.captured?result.monster:5;const enemyWord=$('#enemy-word');enemyWord.textContent=word;enemyWord.classList.add('revealed');
 if(mi===5){$('.hp-fill').style.width=game.bossHp/3*100+'%';$('.hp-count').textContent=`能量 ${game.bossHp} / 3 · ${game.bossHp?'再完成 '+game.bossHp+' 題考驗':'成功成為夥伴！'}`;const track=$('.hp-track');track.setAttribute('aria-valuenow',game.bossHp);}
 else {$('.hp-fill').style.width='0%';$('.hp-track').setAttribute('aria-valuenow','0');}
 $('#score-count').textContent=score;$('#capture-count').textContent=game.captures.length;
 $('#encounter-bubble').innerHTML=result.captured?`${MONSTERS[mi].name} 收到了你的訊號！<br>恭喜！新的夥伴加入冒險。`:'訊號成功！守護者能量減少了。<br>再接再厲，就快成為好朋友！';
 renderResult(gained);runBattleAction(result.captured?'capture':'hit',mi);
}
function renderResult(gained=round.assisted?50:round.attempts===1?100:70){const r=round.result;$('#computer-screen').innerHTML=`<div class="result-row" role="status"><div><div class="eyebrow">${r.captured?'NEW FRIEND CAPTURED!':'GREAT SIGNAL!'}</div><div class="result-word">${esc(round.card.english)}<small>${esc(round.card.pos_zh)} · ${esc(round.card.meaning_zh)}</small></div><p>${r.captured?`成功捕捉 ${MONSTERS[r.monster].name}！`:`魔王能量 −1，還有 ${game.bossHp} 格。`} +${gained} 分</p></div><button class="next-button" data-action="next" ${actionBusy?'disabled':''}>${r.done?'看看冒險成果':r.captured&&game.boss?'前往魔王關卡':r.captured?'尋找下一位夥伴':'繼續魔王考驗'}${icon('arrow')}</button></div>`;}

function lockBattleControls(value){$('#computer-screen')?.setAttribute('aria-busy',String(value));document.querySelectorAll('#computer-screen button').forEach(b=>{if(value){if(!b.disabled){b.dataset.actionLocked='true';b.disabled=true;}}else if(b.dataset.actionLocked){delete b.dataset.actionLocked;b.disabled=false;}});}
function stopBattleAction(){if(!battleAction)return;battleAction.cancel();battleAction=null;actionBusy=false;lockBattleControls(false);if(round?.phase==='success'&&round.result?.captured)$('#enemy-wrap')?.classList.add('captured');}
async function runBattleAction(kind,index){stopBattleAction();stopSpeech();if(kind==='wrong')waitingForAudio=true;actionBusy=true;lockBattleControls(true);const activeRound=round,action=battleAction=new BattleAction($('.arena'),sound,speaker);try{await action.play(kind,index,round.result?.done);}catch{toast('動畫已結束，可以繼續冒險。');}if(battleAction!==action||round!==activeRound)return;action.clean();battleAction=null;actionBusy=false;lockBattleControls(false);lastTick=Date.now();if(kind==='wrong'&&view==='game'&&!paused&&!modal.open)speak(round.card.english,{first:true});}

function confetti(target){const colors=['#f8dd88','#b7d6a8','#e8b6c9','#c6b6e2'];target.insertAdjacentHTML('beforeend',`<div class="sparkles">${Array.from({length:20},(_,i)=>`<i style="left:${45+Math.random()*40}%;top:${10+Math.random()*30}%;background:${colors[i%4]};animation-delay:${Math.random()*.4}s;transform:rotate(${i*13}deg)"></i>`).join('')}</div>`);}
function tick(){const now=Date.now(),elapsed=now-lastTick;lastTick=now;if(view!=='game'||!round||round.phase!=='question'||paused||actionBusy||modal.open||waitingForAudio||!settings.timed)return;remainingMs=Math.max(0,remainingMs-elapsed);const left=$('#time-left'),badge=$('#timer-badge');if(left)left.textContent=Math.ceil(remainingMs/1000)+'s';badge?.classList.toggle('urgent',remainingMs<6000);if(remainingMs===0)timeout();}
function timeout(){round.phase='timeout';round.attempts++;game.answer(false);stopSpeech();sfx('wrong');waitingForAudio=false;$('#enemy-word').textContent=round.card.english;$('#enemy-word').classList.add('revealed');renderTimeout();toast('這題不扣魔王血量，也不會失去已捕捉的夥伴。');}
function renderTimeout(){$('#computer-screen').innerHTML=`<div class="result-row"><div><div class="eyebrow">TAKE A LITTLE BREATH</div><div class="result-word">${esc(round.card.english)}<small>${esc(round.card.meaning_zh)}</small></div><p>時間到了，夥伴還在等你。聽一次、記起來，再挑戰一題！</p></div><button class="next-button" data-action="next">再挑戰一次${icon('arrow')}</button></div>`;}
function pauseMarkup(){return `<div class="pause-cover"><div class="brand-icon">${icon('leaf')}</div><h2>冒險暫停中</h2><p>休息一下，夥伴會等你回來。</p><button class="next-button" data-action="resume">繼續冒險${icon('arrow')}</button><button class="help-button" data-action="confirm-home">返回開始選單</button></div>`;}
function pause(){if(view!=='game'||paused)return;stopBattleAction();paused=true;stopSpeech();$('.arena').insertAdjacentHTML('beforeend',pauseMarkup());}
function resume(){if(view!=='game')return;paused=false;$('.pause-cover')?.remove();lastTick=Date.now();if(waitingForAudio&&round.phase==='question')speak(round.card.english,{first:true});}
function openModal(content){stopBattleAction();if(view==='game'&&!paused){modalPaused=true;paused=true;stopSpeech();}else modalPaused=false;modal.innerHTML=content;modal.showModal();}
function modalHeading(title,description=''){return `<div class="modal-heading"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div><button class="close-button" data-action="close-modal" aria-label="關閉">${icon('close')}</button></div>`;}
function showCollection(){openModal(modalHeading('我的夥伴圖鑑',`已遇見 ${Object.keys(progress.captured).length} / 6 種夥伴 · 紀錄保存在這台裝置`)+`<div class="collection-grid">${MONSTERS.map((m,i)=>`<article class="collection-card ${progress.captured[m.id]?'':'locked'}"><span class="caught-mark">${progress.captured[m.id]?icon('check')+' 捕捉 '+progress.captured[m.id]+' 次':'尚未捕捉'}</span>${sprite(i)}<small>NO. 00${i+1} · ${m.type}</small><h3>${m.name}</h3><small>${m.en}</small><p>${m.description}</p></article>`).join('')}</div>`);}
function showRecords(){const words=Object.keys(progress.words).sort();openModal(modalHeading('每一步，都有成長。','你的學習足跡 · 保存在目前瀏覽器')+`<div class="records-summary"><div class="record-number"><strong>${words.length}</strong>練習過的單字</div><div class="record-number"><strong>${progress.adventures}</strong>完成的冒險</div><div class="record-number"><strong>${progress.bestScore}</strong>最佳分數</div></div><div class="word-records">${words.length?words.map(w=>`<span>${esc(w)} <small style="color:#94a186">×${progress.words[w].correct}</small></span>`).join(''):'<p class="empty-note">第一個單字，就從今天開始！完成一道捕捉考驗，足跡就會出現在這裡。</p>'}</div>`);}
function showSoundSettings(){openModal(modalHeading('讓冒險有自己的聲音','背景音樂、捕捉音效與美語可以分別調整。')+`<div class="audio-settings"><div class="voice-setting"><span class="voice-badge">US</span><div><strong>Jenny · 自然美式英文</strong><p>清楚的標準美語、自然語速與原本音高。</p><small id="voice-status"></small></div><button class="secondary-button" data-action="preview-voice">${icon('sound')}試聽 flower</button></div>${[['music','日系冒險配樂','原創八音盒、撥弦與長笛旋律','musicVolume'],['sfx','遊戲音效','捕捉、選字、拼字與園區互動','sfxVolume']].map(([key,label,note,volume])=>`<div class="audio-control"><div class="audio-control-top"><div><strong>${label}</strong><small>${note}</small></div><button class="audio-toggle ${settings[key]?'on':''}" data-action="toggle-audio" data-setting="${key}" aria-pressed="${settings[key]}" aria-label="${label}開關">${settings[key]?'已開啟':'已關閉'}</button></div><label class="volume-line" for="${volume}"><span>音量</span><input id="${volume}" type="range" min="0" max="100" value="${Math.round(settings[volume]*100)}" data-volume="${volume}" aria-label="${label}音量"><output id="${volume}-value">${Math.round(settings[volume]*100)}%</output></label></div>`).join('')}<div class="audio-control"><label class="volume-line" for="voiceVolume"><span>美語音量</span><input id="voiceVolume" type="range" min="15" max="100" value="${Math.round(settings.voiceVolume*100)}" data-volume="voiceVolume" aria-label="美語音量"><output id="voiceVolume-value">${Math.round(settings.voiceVolume*100)}%</output></label></div><p class="audio-hint">唸單字時，配樂會自動降低音量；換到其他分頁時配樂暫停。第一次點擊畫面後才會開始播放。</p></div>`);updateVoiceStatus();speaker.ready.then(()=>updateVoiceStatus());}
function help(){openModal(modalHeading('小研究員冒險指南','戴上耳機或打開喇叭，一起出發！')+`<div class="help-content"><h3>先選 Week 或 Lesson</h3><p>開頭選單直接顯示 CET Week 與 FET Lesson。點一個課次開始選擇，接著可複選；「全部課次」會恢復全部字庫。CET 的 Week 1–2 是同一組。</p><h3>聽音選字與字母拼拼</h3><p>聽 Jenny 的美語，從四個選項選單字，或依序點字母。重複字母各用一次，grown-up 的連字號也要排入。答錯可以再試，上方字母可退回。</p><h3>對戰動作</h3><p>答對時研究員舉起電腦發射光束，怪物受擊後會加入夥伴；魔王要累積三次命中。答錯時怪物會衝刺反擊，研究員用護盾擋住，接著再聽一次單字。動作期間暫停倒數，可以安心重試。</p><h3>魔王與時間</h3><p>捕捉五隻小怪後挑戰花冠星龍！魔王有三格血量，答對三題就能捕捉。限時模式每題 15、25 或 40 秒；首次發音完畢才開始倒數，重聽不會重置時間。切分頁、查看園區或打開設定會暫停題目。</p><h3>夥伴園區</h3><p>已捕捉的夥伴會在園區自由散步，點牠們可以打招呼。「集合」會讓夥伴靠近，「點心時間」會吸引牠們來吃點心。進入園區不會失去目前關卡。</p><h3>聲音與學習紀錄</h3><p>上方「聲音設定」可開關配樂及音效、調整音量，並試聽標準美語。紀錄保存在這台裝置；換裝置不會自動同步。</p><h3>需要提示時</h3><p>按喇叭重聽，或使用單字提示。無提示首次答對 100 分，重試答對 70 分，提示後答對 50 分。</p></div>`);}
function showPark(){if(view==='park')return;stopBattleAction();parkReturnView=view;parkWasPaused=paused;if(view==='game')paused=true;stopSpeech();stopPark();view='park';sound.setScene('park');window.scrollTo(0,0);const owned=MONSTERS.map((m,index)=>({...m,index})).filter(m=>progress.captured[m.id]>0);app.innerHTML=`${header()}<main class="park-page"><div class="park-heading"><div><div class="eyebrow">LITTLE FRIENDS, BIG HAPPY DAYS</div><h1>我們的<span>夥伴園區</span></h1><p>讓每次單字冒險，長成一座熱鬧的小樂園。</p></div><button class="secondary-button" data-action="park-back">${icon('back')}${parkReturnView==='game'?'回到這趟冒險':'返回開始選單'}</button></div><div class="park-toolbar"><div class="park-count">${icon('leaf')}<strong>${owned.length} / 6</strong> 種夥伴入住</div><div class="park-actions"><button data-action="park-gather" ${owned.length?'':'disabled'}>${icon('sparkle')}集合</button><button data-action="park-feed" ${owned.length?'':'disabled'}>點心時間</button><button data-action="collection">${icon('book')}夥伴圖鑑</button></div></div><section class="park-world" id="park-world" aria-label="已捕捉怪物自由走動的園區"><div class="park-sign">WORDLING GARDEN<small>芽光夥伴園區</small></div><div class="park-weather">☀ 晴朗 · 今天也適合散步</div><div class="park-picnic" aria-hidden="true"><span>✦</span><i></i><i></i><i></i></div>${owned.map(m=>`<button class="park-creature" data-action="pet-monster" data-park-id="${m.id}" aria-label="跟 ${m.name} 打招呼"><span class="park-shadow"></span><span class="park-face">${sprite(m.index,'park-sprite')}</span><span class="park-monster-name">${m.name}</span><span class="park-heart" aria-hidden="true">♡</span></button>`).join('')}${owned.length?'':`<div class="empty-park"><span class="brand-icon">${icon('leaf')}</span><h2>園區正在等第一位夥伴。</h2><p>完成一道單字捕捉考驗，牠就會搬進來！</p><button class="next-button" data-action="park-back">去冒險，交朋友${icon('arrow')}</button></div>`}<div class="park-activity" id="park-activity" role="status">${owned.length?'夥伴正在自由散步。點點牠們，說聲 hello！':'每一次練習，都會帶來新的相遇。'}</div></section><div class="park-bottom"><section class="park-detail" id="park-detail">${owned.length?parkDetail(owned[0].index):'<div><strong>準備好迎接新朋友了嗎？</strong><p>你捕捉的夥伴會保存在目前瀏覽器，下次回來牠們還在。</p></div>'}</section><div class="park-residents" aria-label="園區居民">${MONSTERS.map((m,i)=>`<button class="resident-token ${progress.captured[m.id]?'':'locked'}" data-action="park-focus" data-index="${i}" title="${progress.captured[m.id]?m.name:'尚未捕捉 '+m.name}" aria-label="${progress.captured[m.id]?'查看':'尚未捕捉'} ${m.name}">${sprite(i)}<small>${progress.captured[m.id]?'✓':'?'}</small></button>`).join('')}</div></div><p class="park-save-note">只顯示真正捕捉過的夥伴 · 圖鑑與園區使用同一份本機紀錄</p></main>`;park=new MonsterPark($('#park-world'),owned,{onPet:c=>{sound.cry(c.index);speak('@pet');$('#park-detail').innerHTML=parkDetail(c.index);$('#park-activity').textContent=`${MONSTERS[c.index].name} 開心地向你打招呼：「今天也一起加油！」`;}});}
function parkDetail(index){const m=MONSTERS[index];return `${sprite(index,'park-detail-sprite')}<div><small>${m.type} · ${m.en}</small><h2>${m.name}<span>已捕捉 ${progress.captured[m.id]||0} 次</span></h2><p>${m.description}</p></div>`;}
function backFromPark(){stopSpeech();stopPark();if(parkReturnView==='game'&&game){paused=parkWasPaused;renderBattle();lastTick=Date.now();if(!paused&&waitingForAudio&&round.phase==='question')speak(round.card.english,{first:true});}else renderHome();}
function confirmHome(){if(view!=='game')return renderHome();if(!paused)pause();openModal(modalHeading('先回研究基地嗎？','已捕捉的夥伴和練習紀錄會保留，這趟關卡進度會結束。')+`<div class="finish-actions"><button class="secondary-button" data-action="close-modal">繼續這趟冒險</button><button class="next-button" data-action="leave-game">返回開始選單${icon('arrow')}</button></div>`);}
function finish(){stopPark();sound.setScene('home');window.scrollTo(0,0);stopSpeech();clearInterval(timerId);view='finish';progress.adventures++;progress.bestScore=Math.max(progress.bestScore,score);save();app.innerHTML=`${header()}<main class="finish-page"><div class="finish-eyebrow">ADVENTURE COMPLETE</div><h1>今天，也交到新朋友了！</h1><p>你和花冠星龍通過了單字考驗。<br>帶著這些小小的進步，繼續探索更大的世界吧。</p><div class="finish-monsters">${MONSTERS.map((m,i)=>sprite(i)).join('')}</div><div class="records-summary"><div class="record-number"><strong>${score}</strong>冒險總分</div><div class="record-number"><strong>6 / 6</strong>夥伴成功加入</div><div class="record-number"><strong>${Math.round(game.correct/game.attempts*100)}%</strong>作答正確率</div></div>${!storageOK?'<p class="saved-warning">此瀏覽器無法保存進度，請保持此頁開啟。</p>':''}<div class="finish-actions"><button class="secondary-button" data-action="park">去夥伴園區看看</button><button class="secondary-button" data-action="home">調整課次</button><button class="next-button" data-action="start">再去冒險一次${icon('arrow')}</button></div><section class="learned-list"><h3>今天的單字收藏 · 點喇叭再聽一次</h3><div class="learned-chips">${sessionWords.map(c=>`<span class="learned-chip">${esc(c.english)}<small>${esc(c.meaning_zh)}</small><button data-action="speak-word" data-word="${esc(c.english)}" aria-label="唸出 ${esc(c.english)}">${icon('sound')}</button></span>`).join('')}</div></section></main>`;}
function chooseLetter(id){if(actionBusy||round?.phase!=='question'||paused||round.mode!=='spell'||round.selected.includes(id))return;sfx('letter');round.selected.push(id);round.message='';updateQuestion();if(round.selected.length===round.letters.length){const word=round.selected.map(n=>round.letters.find(t=>t.id===n).letter).join('');submitAnswer(word);}}
function dispatch(action,target){if(actionBusy&&['answer','letter','unletter','backspace','clear-letters','replay','hint','next'].includes(action))return;switch(action){
 case'mode':settings.mode=target.dataset.value;save();renderHome();break;
 case'timed':settings.timed=target.dataset.value==='true';save();renderHome();break;
 case'course':settings.course=target.dataset.value;settings.scope='all';settings.groupIds=[];save();renderHome();break;
 case'unit':{const id=target.dataset.value;if(settings.scope==='all'){settings.groupIds=[];settings.scope='custom';}if(settings.groupIds.includes(id))settings.groupIds=settings.groupIds.filter(n=>n!==id);else settings.groupIds.push(id);save();renderHome(true);break;}
 case'course-all':settings.scope='custom';settings.groupIds=data.groups.filter(g=>g.course===target.dataset.course).map(g=>g.id);save();renderHome();break;
 case'all-units':settings.scope='all';settings.groupIds=[];save();renderHome(true);break;
 case'clear-units':settings.scope='custom';settings.groupIds=[];save();renderHome(true);break;
 case'start':startGame();break;
 case'answer':submitAnswer(target.dataset.word);break;
 case'letter':chooseLetter(Number(target.dataset.id));break;
 case'unletter':if(round?.phase==='question'&&!paused){round.selected.splice(Number(target.dataset.index),1);updateQuestion();}break;
 case'backspace':if(round?.phase==='question'&&!paused){round.selected.pop();updateQuestion();}break;
 case'clear-letters':if(round?.phase==='question'&&!paused){round.selected=[];updateQuestion();}break;
 case'replay':if(!paused)speak(round.card.english,{first:waitingForAudio});break;
 case'speak-word':speak(target.dataset.word);break;
 case'hint':if(round?.phase==='question'&&!paused){round.assisted=true;round.message=`提示：${round.card.english} — ${round.card.meaning_zh}（此題 50 分）`;$('#enemy-word').textContent=round.card.english;$('#enemy-word').classList.add('revealed');updateQuestion();}break;
 case'next':if(!paused&&round.phase!=='question')nextRound();break;
 case'pause':pause();break;
 case'resume':resume();break;
 case'home':if(view==='game')confirmHome();else if(view==='park'&&parkReturnView==='game'){backFromPark();confirmHome();}else{stopSpeech();window.scrollTo(0,0);renderHome();}break;
 case'confirm-home':confirmHome();break;
 case'leave-game':modal.close();clearInterval(timerId);stopSpeech();paused=false;game=null;round=null;window.scrollTo(0,0);renderHome();break;
 case'park':showPark();break;
 case'park-back':backFromPark();break;
 case'park-gather':park?.gather();sfx('start');$('#park-activity').textContent='集合囉！夥伴們正朝你走過來。';break;
 case'park-feed':park?.feed();sfx('feed');$('#park-activity').textContent='點心時間！大家都往野餐墊走來了。';break;
 case'pet-monster':park?.pet(target.dataset.parkId);break;
 case'park-focus':{const i=Number(target.dataset.index);if(progress.captured[MONSTERS[i].id])park?.pet(MONSTERS[i].id);else toast('先在冒險裡捕捉 '+MONSTERS[i].name+'，牠就會搬進園區！');break;}
 case'sound-settings':showSoundSettings();break;
 case'preview-voice':speak('flower');break;
 case'toggle-audio':{const key=target.dataset.setting;settings[key]=!settings[key];sound.activate();sound.update();save();target.classList.toggle('on',settings[key]);target.setAttribute('aria-pressed',settings[key]);target.textContent=settings[key]?'已開啟':'已關閉';if(key==='sfx'&&settings.sfx)sfx('pet');break;}
 case'collection':showCollection();break;
 case'records':showRecords();break;
 case'help':help();break;
 case'close-modal':stopSpeech();modal.close();break;
 case'sfx':settings.sfx=!settings.sfx;sound.update();save();target.textContent=(settings.sfx?'關閉':'開啟')+'捕捉音效';break;
}}
document.addEventListener('pointerdown',()=>sound.activate(),{once:true});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;if(modal.open&&!modal.contains(target))return;dispatch(target.dataset.action,target);});
document.addEventListener('input',e=>{const key=e.target.dataset.volume;if(!key)return;settings[key]=Number(e.target.value)/100;sound.update();save();$('#'+key+'-value').textContent=e.target.value+'%';});
document.addEventListener('change',e=>{if(e.target.id==='seconds'){settings.seconds=Number(e.target.value);save();}});
modal.addEventListener('close',()=>{stopSpeech();if(modalPaused&&view==='game'){paused=false;lastTick=Date.now();if(waitingForAudio&&round.phase==='question')speak(round.card.english,{first:true});}modalPaused=false;});
document.addEventListener('keydown',e=>{if(view!=='game'||modal.open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();paused?resume():pause();return;}if(paused||actionBusy)return;if(e.code==='Space'){e.preventDefault();if(round.phase==='question')speak(round.card.english,{first:waitingForAudio});return;}if(round.phase!=='question'){if(e.key==='Enter'){e.preventDefault();nextRound();}return;}if(round.mode==='choice'&&/^[1-4]$/.test(e.key)){e.preventDefault();const word=round.options[Number(e.key)-1];if(!round.wrong.includes(word))submitAnswer(word);}else if(round.mode==='spell'){if(e.key==='Backspace'){e.preventDefault();round.selected.pop();updateQuestion();}else if(/^[a-zA-Z-]$/.test(e.key)){e.preventDefault();const tile=round.letters.find(t=>t.letter===e.key.toLowerCase()&&!round.selected.includes(t.id));if(tile)chooseLetter(tile.id);}}});
document.addEventListener('visibilitychange',()=>{sound.setVisible(!document.hidden);if(document.hidden){stopSpeech();if(view==='game'&&!modal.open)pause();}});
try{const response=await fetch('data/vocabulary.json');if(!response.ok)throw Error('字庫下載失敗');data=await response.json();if(!data.cards?.length||!data.groups?.length)throw Error('字庫格式不完整');settings.groupIds=settings.groupIds.filter(id=>data.groups.some(g=>g.id===id));if(!['ALL','CET','FET'].includes(settings.course))settings.course='ALL';if(!['choice','spell','mixed'].includes(settings.mode))settings.mode='mixed';if(![15,25,40].includes(settings.seconds))settings.seconds=25;renderHome();}catch(e){app.innerHTML=`<main class="error-box"><h1>字庫還沒準備好</h1><p>請確認以網站網址開啟遊戲，並重新整理頁面。</p><p>${esc(e.message)}</p><button class="next-button" onclick="location.reload()">重新載入</button></main>`;}
